{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyPdmj//hL8qBCTAFJGOD+dL"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"markdown","source":["### **เตรียม app.py และ requirements.txt**"],"metadata":{"id":"hpbZzDyjnfZu"}},{"cell_type":"markdown","source":["# **สร้าง Streamlit Web Application**"],"metadata":{"id":"mWupmzPOnmXi"}},{"cell_type":"code","execution_count":2,"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"rwVTk9lUmly-","executionInfo":{"status":"ok","timestamp":1791213283253,"user_tz":-420,"elapsed":5,"user":{"displayName":"Wanthanee Rathasamuth","userId":"01158365728674962421"}},"outputId":"97a0b37f-5c82-494b-b669-6bfb4508128a"},"outputs":[{"output_type":"stream","name":"stdout","text":["Writing app.py\n"]}],"source":["%%writefile app.py\n","import streamlit as st\n","import pandas as pd\n","import joblib\n","\n","st.set_page_config(page_title=\"Flower Classifier\", page_icon=\"🌸\")\n","st.title(\"🌸 Synthetic Flower Species Classifier\")\n","st.write(\"SVM with tuned RBF kernel\")\n","\n","model = joblib.load(\"svm_flower_model.joblib\")\n","\n","sepal_length = st.slider(\"Sepal length (cm)\", 4.0, 8.0, 5.8, 0.1)\n","sepal_width = st.slider(\"Sepal width (cm)\", 2.0, 4.5, 3.0, 0.1)\n","petal_length = st.slider(\"Petal length (cm)\", 1.0, 7.0, 4.0, 0.1)\n","petal_width = st.slider(\"Petal width (cm)\", 0.1, 2.8, 1.3, 0.1)\n","\n","input_df = pd.DataFrame([{\n","  \"sepal_length_cm\": sepal_length,\n","  \"sepal_width_cm\": sepal_width,\n","  \"petal_length_cm\": petal_length,\n","  \"petal_width_cm\": petal_width\n","}])\n","if st.button(\"Predict species\"):\n","  prediction = model.predict(input_df)[0]\n","  st.success(f\"Predicted species: {prediction}\")"]},{"cell_type":"code","metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"ceab6e38","executionInfo":{"status":"ok","timestamp":1791213885314,"user_tz":-420,"elapsed":43,"user":{"displayName":"Wanthanee Rathasamuth","userId":"01158365728674962421"}},"outputId":"ed18afe1-c5e1-4d16-9fd5-cb13e9b9a0aa"},"source":["%%writefile requirements.txt\n","streamlit\n","pandas\n","scikit-learn\n","joblib"],"execution_count":3,"outputs":[{"output_type":"stream","name":"stdout","text":["Writing requirements.txt\n"]}]}]}